import type { ComponentProps, ReactNode } from 'react'
import { Icon, type IconName } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './InlineAlert.module.css'

export interface InlineAlertProps extends ComponentProps<'div'> {
  variant?: 'info' | 'success' | 'warning' | 'danger'
  size?: 'sm' | 'md'
  /** Replaces the variant's icon; `false` shows none. */
  icon?: ReactNode | false
  /** A short link or button after the message, e.g. "Retry". */
  action?: ReactNode
  /**
   * Announce it when it appears: `danger` and `warning` interrupt
   * (`role="alert"`), the others wait (`role="status"`).
   */
  isLive?: boolean
}

const icons: Record<NonNullable<InlineAlertProps['variant']>, IconName> = {
  info: 'info',
  success: 'success',
  warning: 'warning',
  danger: 'danger',
}

/**
 * A one-line message in the flow of a form or a section: no box, no title,
 * no close button. For a message about a whole page or region, use Alert.
 */
export function InlineAlert({
  variant = 'info',
  size = 'md',
  icon,
  action,
  isLive = false,
  className,
  children,
  ...props
}: InlineAlertProps) {
  const urgent = variant === 'danger' || variant === 'warning'
  return (
    <div
      role={isLive ? (urgent ? 'alert' : 'status') : undefined}
      className={cn(styles.inlineAlert, styles[variant], styles[size], className)}
      {...props}
    >
      {icon !== false && (
        <span className={styles.icon} aria-hidden="true">
          {icon ?? <Icon name={icons[variant]} />}
        </span>
      )}
      <span className={styles.message}>{children}</span>
      {action && <span className={styles.action}>{action}</span>}
    </div>
  )
}

.inlineAlert {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  /* The whole line takes the variant's text colour, measured at 4.5:1 on
     the page: an inline alert has no box to carry the colour instead. */
  color: var(--inline-alert-text);
}

.sm {
  gap: var(--space-1-5);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
}

.info {
  --inline-alert-text: var(--info-text);
}
.success {
  --inline-alert-text: var(--success-text);
}
.warning {
  --inline-alert-text: var(--warning-text);
}
.danger {
  --inline-alert-text: var(--danger-text);
}

/* One line tall, so the icon sits on the first line of a wrapped message.
   --leading-* is a ratio; times the text size it is a length. */
.icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  block-size: calc(var(--leading-body) * var(--text-body));
  font-size: var(--space-4);
}
.sm .icon {
  block-size: calc(var(--leading-body-sm) * var(--text-body-sm));
  font-size: var(--space-3);
}

.message {
  min-inline-size: 0;
}

.action {
  flex-shrink: 0;
  margin-inline-start: var(--space-1);
}
